edits.oldText:
function onReady() {
  setCopyrightYear();
  initHeaderScroll();
  setActiveNav();
  updateCartBadge();
  initLightboxUi();
  initCartButton();
  initComingSoonTriggers();
  injectCartModal();
  initModalEscape();
  // Call initReveal for any static reveal elements on the page
  // (page-specific dynamic content calls initReveal inside render functions)
  initReveal();

  var page = document.body && document.body.dataset.page;
  if (page === "home") initHome();
  else if (page === "store") initStorePage();
  else if (page === "coolgallery") {
    initCoolGalleryPage();
  }
  else if (page === "product") initProductPage();
  else if (page === "cart") {
    renderCartPage();
  }
}

