            <p class="eyebrow">${escapeHtml(p.category)}</p>
            <h1 style="font-size: clamp(1.75rem, 4vw, 2.25rem); margin: 0 0 0.5rem; line-height: 1.2;">${escapeHtml(p.title)}</h1>
